CREATE OR REPLACE FUNCTION public.tipo_participante_diario(_codigo text) RETURNS text LANGUAGE sql IMMUTABLE SET search_path=public AS $$ SELECT CASE WHEN btrim(_codigo) ~ '^[0-9]+$' THEN CASE WHEN btrim(_codigo)::numeric BETWEEN 100000 AND 499999 THEN '4-Cli. Nac.' WHEN btrim(_codigo)::numeric >= 500000 THEN '5-For. Nac.' END END $$;
DO $$ DECLARE d text; BEGIN SELECT pg_get_functiondef('public.contas_novas_da_empresa(uuid,uuid,integer)'::regprocedure) INTO d; d := replace(d, 'WHEN _larg IS NULL OR m.conta_codigo', 'WHEN public.tipo_participante_diario(m.conta_codigo) IS NOT NULL THEN public.tipo_participante_diario(m.conta_codigo)' || chr(10) || '        WHEN _larg IS NULL OR m.conta_codigo'); EXECUTE d; END $$;
CREATE OR REPLACE FUNCTION public.carimbo_dados_empresa(_company_id uuid) RETURNS TABLE(linhas bigint, atualizado_em timestamptz) LANGUAGE sql STABLE SET search_path=public AS $$
SELECT (SELECT count(*) FROM public.saldos_mensais WHERE company_id=_company_id) + (SELECT count(*) FROM public.saldos_abertura WHERE company_id=_company_id) + (SELECT count(*) FROM public.depara_contas WHERE company_id=_company_id) + (SELECT count(*) FROM public.plano_contas WHERE company_id=_company_id), greatest((SELECT max(updated_at) FROM public.saldos_mensais WHERE company_id=_company_id), (SELECT max(created_at) FROM public.saldos_abertura WHERE company_id=_company_id), (SELECT max(updated_at) FROM public.saldo_inicial_uploads WHERE company_id=_company_id), (SELECT max(updated_at) FROM public.depara_contas WHERE company_id=_company_id), (SELECT max(p.updated_at) FROM public.plano_contas p JOIN public.companies c ON c.id=_company_id WHERE p.tenant_id=c.tenant_id AND (p.company_id IS NULL OR p.company_id=_company_id)), (SELECT max(i.updated_at) FROM public.indicadores_empresa i JOIN public.companies c ON c.id=_company_id WHERE i.tenant_id=c.tenant_id AND (i.company_id IS NULL OR i.company_id=_company_id))) $$;
CREATE OR REPLACE FUNCTION public.conferir_contas_diario(_company_id uuid, _inicio date DEFAULT NULL, _fim date DEFAULT NULL, _busca text DEFAULT '', _offset integer DEFAULT 0) RETURNS TABLE(codigo text, nome text, debitos numeric, creditos numeric, lancamentos bigint, tipo_esperado text, destino_codigo text, destino_classificacao text, destino_nome text, ignorada boolean, total bigint) LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public SET statement_timeout='60s' AS $$
DECLARE _tenant uuid;
BEGIN
IF NOT public.pode_acessar_empresa(_company_id) THEN RAISE EXCEPTION 'Sem permissão'; END IF;
SELECT tenant_id INTO _tenant FROM public.companies WHERE id=_company_id;
RETURN QUERY WITH mov AS (
SELECT l.conta_codigo, max(nullif(btrim(l.conta_nome),'')) nome, sum(l.debito) d, sum(l.credito) c, count(*) n FROM public.lancamentos_diario l JOIN public.diario_uploads u ON u.id=l.upload_id WHERE l.company_id=_company_id AND u.filename NOT LIKE 'ECD:%' AND (_inicio IS NULL OR l.competencia>=_inicio) AND (_fim IS NULL OR l.competencia<=_fim) GROUP BY l.conta_codigo
), resolvido AS (
SELECT m.*, dc.ignorada ign, coalesce(dc.conta_padrao_codigo,reg.conta_padrao_codigo,m.conta_codigo) dest FROM mov m LEFT JOIN public.depara_contas dc ON dc.company_id=_company_id AND dc.conta_codigo=m.conta_codigo
LEFT JOIN LATERAL (SELECT r.conta_padrao_codigo FROM public.depara_regras r JOIN public.plano_contas po ON po.company_id=_company_id AND po.codigo=m.conta_codigo WHERE r.company_id=_company_id AND (r.tipo_conta IS NULL OR r.tipo_conta=po.tipo) AND (r.classificacao_prefixo IS NULL OR public.cls_no_prefixo(po.classificacao,r.classificacao_prefixo)) ORDER BY length(r.classificacao_prefixo) DESC NULLS LAST LIMIT 1) reg ON dc.conta_padrao_codigo IS NULL
), linhas AS (
SELECT m.conta_codigo cod,coalesce(m.nome,p.descricao,m.conta_codigo) nm,m.d,m.c,m.n,public.tipo_participante_diario(m.conta_codigo) esperado,p.codigo pd,p.classificacao cls,p.descricao descr,coalesce(m.ign,false) ign FROM resolvido m LEFT JOIN LATERAL (SELECT p0.* FROM public.plano_contas p0 WHERE p0.tenant_id=_tenant AND (p0.company_id IS NULL OR p0.company_id=_company_id) AND p0.codigo=m.dest AND p0.ativo ORDER BY p0.company_id NULLS LAST LIMIT 1) p ON true
)
SELECT l.cod,l.nm,l.d,l.c,l.n,l.esperado,l.pd,l.cls,l.descr,l.ign,count(*) OVER() FROM linhas l WHERE coalesce(_busca,'')='' OR l.cod ILIKE '%'||_busca||'%' OR l.nm ILIKE '%'||_busca||'%' ORDER BY l.cod LIMIT 100 OFFSET greatest(0,coalesce(_offset,0));
END $$;
REVOKE ALL ON FUNCTION public.conferir_contas_diario(uuid,date,date,text,integer) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.conferir_contas_diario(uuid,date,date,text,integer) TO authenticated,service_role;